import React, { useEffect, useState } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const Graph = () => {
    const [data, setData] = useState([]);
    const [loading, setLoading] = useState(true);

    const fetchDollarValue = async () => {
        try {
            const response = await fetch('http://localhost:8000/fetch-one?from=USD&to=MXN', {
                headers: {
                    'Authorization': 'Bearer 7487e94f8f-82434b0371-skncut' // Asegúrate de que esta cabecera sea correcta según tu API
                }
            });
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            const result = await response.json();
            const dollarValue = result.value; // Asegúrate de que esta línea sea correcta según la estructura de tu respuesta
            setData(prevData => [
                ...prevData,
                { name: new Date().toLocaleTimeString(), value: dollarValue }
            ]);
            setLoading(false);
        } catch (error) {
            console.error('Error fetching dollar value:', error.message);
        }
    };

    useEffect(() => {
        fetchDollarValue();
        const intervalId = setInterval(fetchDollarValue, 10000); // Actualiza cada 10 segundos

        return () => clearInterval(intervalId); // Limpia el intervalo al desmontar
    }, []);

    return (
        <ResponsiveContainer width="100%" height={300}>
            <LineChart data={data}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" />
                <YAxis />
                <Tooltip />
                <Legend />
                <Line type="monotone" dataKey="value" stroke="#8884d8" />
            </LineChart>
        </ResponsiveContainer>
    );
};

export default Graph;
